import unittest
from decimal import Decimal

from billing import invoice_amount


class InvoiceAmountTests(unittest.TestCase):
    def test_valid_amounts_are_decimal_cents(self):
        self.assertEqual(invoice_amount("1234.5"), Decimal("1234.50"))
        self.assertEqual(invoice_amount(" 1,234.56 "), Decimal("1234.56"))
        self.assertEqual(invoice_amount("0"), Decimal("0.00"))

    def test_invalid_amount_strings_are_rejected(self):
        for value in ("", "-1", "+1", "1.", ".50", "12.345", "1,23", "1,2345", "1e2", "NaN"):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    invoice_amount(value)

    def test_non_string_amounts_are_rejected(self):
        with self.assertRaises(TypeError):
            invoice_amount(1)


if __name__ == "__main__":
    unittest.main()
